import{G as e,K as t,n,ot as r}from"./chunks/framework.C8_jer4d.js";var i=JSON.parse(`{"title":"Trace the dependencies","description":"","frontmatter":{"title":"Trace the dependencies","prev":{"text":"Lab 4: Overview"}},"headers":[],"relativePath":"baw-lab/trace-dependencies/challenge.md","filePath":"baw-lab/trace-dependencies/challenge.md"}`),a={name:`baw-lab/trace-dependencies/challenge.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h2 id="🌊-clue-1-the-ripple-effect" tabindex="-1">🌊 Clue 1 - The Ripple Effect <a class="header-anchor" href="#🌊-clue-1-the-ripple-effect" aria-label="Permalink to “🌊 Clue 1 - The Ripple Effect”">​</a></h2><blockquote><p><em>&quot;Changing a business object is easy. Knowing everything that breaks when you do is the hard part.&quot;</em></p></blockquote><h3 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h3><p>The <code>baw-dependency-mapper</code> skill analyzes how Business Objects (BOs) and variables are used across a process application from its TWX export. It does not need a connection to a BAW server.</p><p>The central challenge it addresses is this: in a BAW application with multiple processes, services, and coaches all sharing the same data structures, it is not obvious what breaks when you rename a field, change a type, or delete a Business Object. The skill maps every place a BO is declared, read, written, bound to a service, or bound to a coach — so you can assess the impact before making a change.</p><p>The lab application is <code>OrderFulfillment.twx</code>, an order fulfillment process application modeling an end-to-end order lifecycle with order placement, validation, inventory check, warehouse operator review, payment processing, and shipment creation. It defines five Business Objects: <code>Address</code>, <code>Customer</code>, <code>Order</code>, <code>OrderLine</code>, and <code>ShipmentDetails</code>.</p><hr><h3 id="🤖-challenge-1-—-ask-bob-to-analyze-the-business-object-dependencies" tabindex="-1">🤖 Challenge 1 — Ask Bob to analyze the Business Object dependencies <a class="header-anchor" href="#🤖-challenge-1-—-ask-bob-to-analyze-the-business-object-dependencies" aria-label="Permalink to “🤖 Challenge 1 — Ask Bob to analyze the Business Object dependencies”">​</a></h3><ol><li><p>In the Bob IDE Explorer panel, expand the <code>lab-4/</code> folder and confirm <code>OrderFulfillment.twx</code> is present. Do <strong>not</strong> open, rename, or move it. The folder also contains a README file. Please don&#39;t open it yet, because it contains the answers to the later challenges.</p></li><li><p>Open the Bob Chat Panel with <strong>Option + Cmd + B</strong> (macOS) or <strong>Ctrl + Alt + B</strong> (Windows/Linux), or click the <strong>Bob icon</strong> beside the navigation bar.</p></li><li><p>Start a <strong>new chat</strong> by clicking the <strong>+</strong> (New Chat) icon at the top of the panel.</p></li><li><p>Click the <strong>+</strong> at the bottom left of the chat input, select <strong>IBM BAW Author</strong> under <strong>Modes</strong>, and enter the following prompt:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Analyze business object dependencies of the following twx file: </span></span>
<span class="line"><span>lab-4/OrderFulfillment.twx. </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Write any output to docs/lab4-output/</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">💡 <strong>Deterministic Scanning &amp; AI Synthesis</strong></p><p>Bob uses deterministic static analysis tools to parse the TWX structure and applies natural language reasoning to synthesize cross-service data flows, answer complex dependency questions, and generate actionable refactoring plans.</p></div></li><li><p>Press <strong>Enter</strong> and click <strong>Approve skill tools for task</strong> when prompted. Approve actions as prompted, and wait until Bob presents the combined dependency summary before starting another prompt or closing the chat.</p></li></ol><div class="info custom-block"><p class="custom-block-title">✅ <strong>Checkpoint</strong></p><ul><li>Bob lists the five Business Objects found in the application (<code>Address</code>, <code>Customer</code>, <code>Order</code>, <code>OrderLine</code>, and <code>ShipmentDetails</code>) and presents a combined dependency summary in the chat.</li><li>In the Explorer, the folder <code>docs/lab4-output/</code> exists and contains <code>&lt;BO&gt;-dependency-report.md</code> and <code>&lt;BO&gt;-dependency-report.json</code> for each Business Object analyzed (for example, <code>Order-dependency-report.md</code> and <code>Order-dependency-report.json</code>). Bob may also create an additional summary file. That&#39;s fine.</li></ul></div><hr><h3 id="📊-challenge-2-—-review-and-navigate-the-dependency-reports" tabindex="-1">📊 Challenge 2 — Review and navigate the dependency reports <a class="header-anchor" href="#📊-challenge-2-—-review-and-navigate-the-dependency-reports" aria-label="Permalink to “📊 Challenge 2 — Review and navigate the dependency reports”">​</a></h3><ol><li><p>In the Explorer, navigate to <code>docs/lab4-output/</code> and open <code>Order-dependency-report.md</code>.</p></li><li><p>Open the Markdown preview to inspect the rendered diagrams and tables: right-click the editor tab and choose <strong>Open Preview</strong>. Alternatively, click once inside the report text in the editor, so the editor has focus rather than the Explorer, and press <strong>Cmd + Shift + V</strong> (macOS) / <strong>Ctrl + Shift + V</strong> (Windows/Linux).</p></li><li><p>Read the <strong>Summary</strong> at the top of the report. It states how many places in the application use <code>Order</code>: <strong>47 locations</strong>.</p></li><li><p>Scroll to the <strong>Dependency graph</strong> and inspect the visual model:</p><ul><li>Locate the center <strong>Rectangle</strong> (<code>Order</code>) and the <strong>Circle</strong> node representing the BO definition.</li><li>Identify the <strong>Flag shapes</strong> representing services (<code>[service]</code>) and coaches (<code>[coach]</code>) with I/O bindings (<code>ValidateOrder</code>, <code>CheckInventory</code>, <code>ProcessPayment</code>, <code>CreateShipment</code>, etc.).</li><li>Notice the note box indicating nodes omitted for diagram readability (the diagram caps at 20 nodes; complete references are preserved in the tables below).</li></ul></li><li><p>Scroll down to review the detailed usage tables:</p><ul><li><strong>Declarations:</strong> Note the 4 rows (the <code>Order</code> BO definition with 11 fields and the 3 service variable declarations).</li><li><strong>Write usages:</strong> Identify services whose scripts mutate <code>Order</code> data (<code>ValidateOrder</code>, <code>CheckInventory</code>, <code>ProcessPayment</code>).</li><li><strong>Service I/O bindings:</strong> Review services and coaches mapping <code>Order</code> as <code>dataInput</code> or <code>dataOutput</code>.</li><li><strong>Coach bindings:</strong> Review controls bound to specific fields (e.g., <code>orderId</code>, <code>status</code>, <code>totalAmount</code>).</li></ul></li><li><p>Verify writers, coach bindings, and nested objects:</p><ul><li>Answer from the tables: Which three services write to <code>Order</code>, and which coaches bind to <code>Order</code> fields?</li><li>Then <strong>ask Bob</strong> in the same chat session to identify nested Business Objects (since the table preview truncates to the first 8 fields):</li></ul><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Which fields of the Order Business Object are themselves Business Objects,</span></span>
<span class="line"><span>and what are their types?</span></span></code></pre></div><p><em>Expected answer: <code>customer : Customer</code> and <code>lines : OrderLine</code> (a list).</em></p></li></ol><div class="info custom-block"><p class="custom-block-title">✅ <strong>Checkpoint</strong></p><ul><li><code>Order-dependency-report.md</code> opens cleanly in the Markdown preview with a rendered Mermaid diagram and complete usage tables.</li><li>You can identify the three writer services (<code>ValidateOrder</code>, <code>CheckInventory</code>, <code>ProcessPayment</code>) and the four coaches (<code>PlaceOrder</code>, <code>ReviewOrder</code>, <code>ResolveShipmentDelay</code>, <code>HandlePaymentFailure</code>) binding to <code>Order</code> fields.</li><li>Bob&#39;s answer names the nested Business Objects (<code>customer : Customer</code>, <code>lines : OrderLine</code>), and you noticed the report alone doesn&#39;t show them.</li></ul></div><hr><h3 id="🔍-challenge-3-—-evaluate-detected-issues-and-design-defects" tabindex="-1">🔍 Challenge 3 — Evaluate detected issues and design defects <a class="header-anchor" href="#🔍-challenge-3-—-evaluate-detected-issues-and-design-defects" aria-label="Permalink to “🔍 Challenge 3 — Evaluate detected issues and design defects”">​</a></h3><ol><li><p>In the open <code>Order-dependency-report.md</code>, scroll to the <strong>Issues detected</strong> section.</p></li><li><p>Review the specific issues flagged by the static analysis:</p><ul><li>⚠️ <strong>Circular BO reference:</strong> <code>OrderLine → Order → OrderLine</code>. <code>Order.lines</code> is typed as <code>OrderLine</code>, and <code>OrderLine.orderRef</code> points back to <code>Order</code>, so the two types contain each other. The tool flags a loop like this for review. The report notes that such loops can cause problems at runtime, so check that against how your own applications use the type.</li><li>⚠️ <strong>Stale coach bindings:</strong> <code>PlaceOrder</code> and <code>ReviewOrder</code> both bind a UI control to <code>tw.local.order.discount</code>. However, <code>discount</code> does not exist on the <code>Order</code> BO definition (for example, <code>totalAmount</code> exists, but there is no <code>discount</code> field). At runtime, such a control will most likely show nothing, because the field it points to doesn&#39;t exist. A binding to a field that doesn&#39;t exist is easy to overlook when you review coaches one by one. The dependency map finds it in seconds.</li></ul></li><li><p>In the <strong>Service input bindings</strong> table, find <code>ValidateOrder</code> and <code>CheckInventory</code>. Both receive <code>order : Order</code> as <code>dataInput</code>. That alone doesn&#39;t tell you whether one call is unnecessary, so <strong>ask Bob</strong> in the same chat session:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>In the OrderFulfillment process, look at ValidateOrder and CheckInventory. </span></span>
<span class="line"><span>Both receive the Order. Is the second call redundant? Check the process </span></span>
<span class="line"><span>flow and the scripts.</span></span></code></pre></div><p>In Bob&#39;s answer, look for what each service reads from the order and what it changes, and where the process uses those changed values later.</p><p>Bob&#39;s analysis gives you a list of findings to look at. In this lab you only read the results and ask questions, so nothing in the application changes. In a real project, you decide what to change and check each finding in your own application first.</p></li><li><p><strong>Optional:</strong> Open <code>Customer-dependency-report.md</code> and look at the <strong>Issues detected</strong> section. Besides the circular reference, it contains a <strong>Read before write</strong> finding for the activity <code>Check Shipping Region</code> in <code>ValidateOrder</code>. Ask Bob in the same chat session:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>In ValidateOrder, the Check Shipping Region step reads the customer&#39;s </span></span>
<span class="line"><span>shipping address. Is the customer data set before that step runs, and does </span></span>
<span class="line"><span>this need fixing?</span></span></code></pre></div><p>Bob can check the scripts and the Coach bindings in the TWX for you.</p></li></ol><div class="info custom-block"><p class="custom-block-title">✅ <strong>Checkpoint</strong></p><ul><li>You can locate the circular reference warning (<code>OrderLine ↔ Order</code>) and the two stale coach binding warnings (<code>order.discount</code> in <code>PlaceOrder</code> and <code>ReviewOrder</code>).</li><li>You understand what the circular reference means (the two BOs contain each other) and why a binding to a field that doesn&#39;t exist is worth fixing.</li><li>You asked Bob whether the second call is needed, and you can explain Bob&#39;s answer from what each service reads and changes.</li></ul></div><hr><h3 id="⚠️-challenge-4-—-assess-the-impact-of-a-proposed-change" tabindex="-1">⚠️ Challenge 4 — Assess the impact of a proposed change <a class="header-anchor" href="#⚠️-challenge-4-—-assess-the-impact-of-a-proposed-change" aria-label="Permalink to “⚠️ Challenge 4 — Assess the impact of a proposed change”">​</a></h3><ol><li><p>In <code>Order-dependency-report.md</code>, navigate to the <strong>Impact assessment</strong> section.</p></li><li><p>Read the risk assessment for each change scenario:</p><ul><li><strong>🟢 Add Field (Low risk):</strong> Adding a field is backward-compatible; existing consumers are unaffected.</li><li><strong>🔴 Remove Field / Rename Field (High risk):</strong> Breaks any service, script, or coach referencing the field. Lists artifacts that must be updated (<code>CheckInventory</code>, <code>HandlePaymentFailure</code>, <code>PlaceOrder</code>, <code>ProcessPayment</code>, <code>ResolveShipmentDelay</code>, <code>ReviewOrder</code>, <code>ValidateOrder</code>). This list is for any field of <code>Order</code>, so it is a starting point rather than the answer for one specific field.</li><li><strong>🔴 Delete BO (High risk):</strong> Lists everything that uses <code>Order</code>: services, coaches, and the BO itself.</li><li><strong>🔴 Change Field Type (High risk):</strong> Affects the data mapping of every service and coach that uses the field.</li></ul><p>The scenarios apply to any field of <code>Order</code>. To find out what a specific change affects, <strong>ask Bob</strong> in the same chat session what breaks if you rename the <code>totalAmount</code> field:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to rename the totalAmount field to orderTotal in the Order</span></span>
<span class="line"><span>Business Object. What artifacts would break and need to be updated?</span></span></code></pre></div><p>Review Bob&#39;s response and verify:</p><ul><li>Bob names the three coaches that bind to <code>totalAmount</code>: <code>PlaceOrder</code>, <code>ReviewOrder</code>, and <code>HandlePaymentFailure</code>.</li><li>Bob inspects script logic to pinpoint two services using the field: <code>ValidateOrder</code> (<code>totalAmount &lt; 10</code> check) and <code>ProcessPayment</code> (logging).</li><li>Compare Bob&#39;s answer with the <strong>Coach bindings</strong> table in the report to confirm alignment.</li></ul></li><li><p>Ask Bob to turn the analysis into a plan, in the same chat session:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>In what order should I make these changes, and what should I test </span></span>
<span class="line"><span>afterwards?</span></span></code></pre></div><p>Bob proposes an order, typically the Business Object first, then the services, then the coaches, and lists what to test. For example, an order below 10 is still rejected, the payment log shows the amount, and the three coaches show the total. This isn&#39;t in the report. Bob turns the analysis into a work plan.</p></li></ol><div class="info custom-block"><p class="custom-block-title">✅ <strong>Final Checkpoint</strong></p><ul><li>The generated reports exist under <code>docs/lab4-output/</code> for all five Business Objects.</li><li>You have reviewed the dependency graph, usage tables, detected issues (circular reference, stale bindings), and impact assessment matrix.</li><li>Bob&#39;s answer named services (<code>ValidateOrder</code>, <code>ProcessPayment</code>) that the report doesn&#39;t list for the field.</li><li>You can use Bob to evaluate exactly what breaks before modifying, renaming, or deleting a Business Object or its fields.</li></ul></div>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};